package za.co.loopmanager;
import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.Config;import android.content.res.Configuration;import android.view.View;import android.widget.*;import za.co.bacy.ui.Appearance;import za.co.bacy.ui.CustomerHome;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk={30,35})
public class AppearanceTest {
 @After public void reset(){Appearance.select(RuntimeEnvironment.getApplication(),"system");CustomerHome.applyAppearance(RuntimeEnvironment.getApplication());AccountSheets.appearance(RuntimeEnvironment.getApplication());}
 @Test public void explicitPreferenceSurvivesAndOverridesSystem(){var c=RuntimeEnvironment.getApplication();Appearance.select(c,"dark");assertTrue(Appearance.dark(c));assertEquals("dark",Appearance.selected(c));Appearance.select(c,"light");assertFalse(Appearance.dark(c));}
 @Test public void systemChoiceFollowsNightConfiguration(){var c=RuntimeEnvironment.getApplication();Appearance.select(c,"system");Configuration old=new Configuration(c.getResources().getConfiguration()),night=new Configuration(old);night.uiMode=(night.uiMode&~Configuration.UI_MODE_NIGHT_MASK)|Configuration.UI_MODE_NIGHT_YES;assertTrue(Appearance.dark(c.createConfigurationContext(night)));night.uiMode=(night.uiMode&~Configuration.UI_MODE_NIGHT_MASK)|Configuration.UI_MODE_NIGHT_NO;assertFalse(Appearance.dark(c.createConfigurationContext(night)));}
 @Test public void darkActionsKeepReadableTextAndBankControls(){var c=RuntimeEnvironment.getApplication();Appearance.select(c,"dark");AccountSheets.appearance(c);View row=AppControls.action(c,"Banking","Open your bank","bank",AccountSheets.MINT,()->{});LinearLayout copy=(LinearLayout)((LinearLayout)row).getChildAt(1);TextView title=(TextView)copy.getChildAt(0);assertTrue(androidx.core.graphics.ColorUtils.calculateContrast(title.getCurrentTextColor(),AccountSheets.MINT)>4.5);assertTrue(androidx.core.graphics.ColorUtils.calculateContrast(AccountSheets.MUTED,AccountSheets.PAPER)>4.5);}
 @Test public void unknownModeCannotChangeSavedPreference(){var c=RuntimeEnvironment.getApplication();Appearance.select(c,"light");try{Appearance.select(c,"invalid");fail();}catch(IllegalArgumentException expected){}assertEquals("light",Appearance.selected(c));}
}
